class Task:
    def __init__(self, C, T, D):
        self.C = C
        self.T = T
        self.D = D
        self.U = C / T

def calculate_total_utilization(task_set):
    total_U = 0
    for task in task_set:
        total_U += task.U
    return total_U

def get_priority_sets(task_set, task_i):
    hp_i = []
    lp_i = []
    hep_i = []
    lep_i = []
    for task_j in task_set:
        if task_j.priority < task_i.priority:
            hp_i.append(task_j)
        elif task_j.priority > task_i.priority:
            lp_i.append(task_j)

        if task_j.priority <= task_i.priority:
            hep_i.append(task_j)
        elif task_j.priority >= task_i.priority:
            lep_i.append(task_j)
    return hp_i, lp_i, hep_i, lep_i

def calculate_resource_blocking_by_task(task_l, task_i):
    # This would involve analyzing resource access patterns and SRP rules
    # For simplicity, assume a pre-calculated value or a function call
    return task_l.max_resource_hold_time_for_priority(task_i.priority)

def is_taskset_schedulable(task_set, R_values):
    for task_i in task_set:
        if not is_task_schedulable(task_i, R_values[task_i.id]):
            return False
    return True

def calculate_active_period(task_i, task_set, B_i):
    A_i_m = task_i.C # Initial estimate
    while True:
        A_i_m_plus_1 = B_i
        for task_j in task_set:
            if task_j.priority <= task_i.priority: # task_j in hep_i
                A_i_m_plus_1 += math.ceil(A_i_m / task_j.T) * task_j.C

        if A_i_m_plus_1 == A_i_m:
            return A_i_m
        A_i_m = A_i_m_plus_1

import math

def calculate_num_jobs_in_active_period(task_i, A_i):
    return math.ceil(A_i / task_i.T)

import math

def calculate_fnr_start_time(task_i, g, B_i, F_i, hp_i):
    w_i_g_NP_m = B_i + g * task_i.C + F_i # Initial estimate
    deadline_g = g * task_i.T + task_i.D

    while True:
        w_i_g_NP_m_plus_1 = B_i + g * task_i.C + F_i
        for task_j in hp_i:
            w_i_g_NP_m_plus_1 += math.ceil(w_i_g_NP_m / task_j.T) * task_j.C

        if w_i_g_NP_m_plus_1 == w_i_g_NP_m:
            if w_i_g_NP_m_plus_1 > deadline_g:
                return float('inf') # Unschedulable
            return w_i_g_NP_m

        if w_i_g_NP_m_plus_1 > deadline_g and w_i_g_NP_m_plus_1 > w_i_g_NP_m: # Check for divergence beyond deadline
            return float('inf') # Unschedulable

        w_i_g_NP_m = w_i_g_NP_m_plus_1

import math

def calculate_execution_completed(task_i, g, t, B_i, hp_i):
    interference = 0
    for task_j in hp_i:
        interference += math.ceil(t / task_j.T) * task_j.C

    completed_execution = t - B_i - g * task_i.C - interference
    return max(0, completed_execution)

def calculate_min_fnr_for_job(task_i, P_i_g, S_i_g_t_values):
    if not P_i_g:
        return float('inf') # Job is unschedulable

    max_S_i_g_t = 0
    for t in P_i_g:
        max_S_i_g_t = max(max_S_i_g_t, S_i_g_t_values[t]) # S_i_g_t_values is a map from t to S_i_g_t

    return max(1, task_i.C - max_S_i_g_t)

def calculate_min_fnr_for_task(task_i, G_i, F_i_g_values):
    max_F_i_g = 0
    for g in range(G_i):
        max_F_i_g = max(max_F_i_g, F_i_g_values[g])

    if max_F_i_g > task_i.C:
        return float('inf') # Task is unschedulable, FNR too long
    return max_F_i_g
